create table if not exists public.communication_safeguarding_policies (id uuid primary key default gen_random_uuid(), tenant_id uuid, organization_id uuid, policy_name text not null, applies_to_minors boolean not null default true, guardian_visibility_required boolean not null default false, direct_message_allowed boolean not null default true, attachment_allowed boolean not null default true, retention_days integer, moderation_required boolean not null default false, status text not null default 'active', effective_from date not null default current_date, effective_until date, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.communication_guardian_links (id uuid primary key default gen_random_uuid(), tenant_id uuid, athlete_id uuid not null references public.athletes(id) on delete cascade, guardian_person_id uuid not null, communication_scope text not null default 'all', status text not null default 'active', valid_from timestamptz not null default now(), valid_until timestamptz, source text not null default 'family_authority', created_at timestamptz not null default now(), unique(athlete_id,guardian_person_id,communication_scope));
create table if not exists public.communication_moderation_events (id uuid primary key default gen_random_uuid(), tenant_id uuid, message_id uuid references public.communication_messages(id) on delete cascade, actor_person_id uuid, event_type text not null, reason text, disposition text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.finance_reconciliation_runs (id uuid primary key default gen_random_uuid(), tenant_id uuid, organization_id uuid, provider text not null, period_start date, period_end date, status text not null default 'running', expected_amount numeric, settled_amount numeric, variance_amount numeric, started_at timestamptz not null default now(), completed_at timestamptz, metadata jsonb not null default '{}'::jsonb);
create table if not exists public.finance_reconciliation_items (id uuid primary key default gen_random_uuid(), reconciliation_run_id uuid not null references public.finance_reconciliation_runs(id) on delete cascade, payment_id uuid, refund_id uuid, external_reference text, expected_amount numeric, settled_amount numeric, variance_amount numeric, status text not null default 'pending', notes text, created_at timestamptz not null default now());
create table if not exists public.accounting_exports (id uuid primary key default gen_random_uuid(), tenant_id uuid, organization_id uuid, export_type text not null, provider text, period_start date, period_end date, status text not null default 'queued', storage_reference text, checksum text, generated_at timestamptz, generated_by_person_id uuid, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.accounting_mappings (id uuid primary key default gen_random_uuid(), tenant_id uuid, organization_id uuid, provider text not null, ls1_account_code text not null, external_account_code text not null, mapping_type text not null default 'account', status text not null default 'active', metadata jsonb not null default '{}'::jsonb, unique(organization_id,provider,ls1_account_code,mapping_type));
update public.platform_capability_registry set status='schema_ready',updated_at=now() where capability_key <> 'coach_decision_engine';
